public class OrderService {
    public void createOrder(Order order) {
        try {
            orderRepository.save(order); // triggers database constraint
        } catch (DataAccessException e) {
            // Wrap low-level DB exception in business exception
            throw new OrderException("Failed to process order " + order.getId(), e);
        }
    }
}

// The REAL cause is at the bottom: duplicate order ID
// Top exception just says "failed" but root cause says WHY

// Java 14+ output:
// java.lang.NullPointerException: Cannot invoke "Address.getCity()" because the return value of "Customer.getAddress()" is null
//     at com.example.order.OrderService.validateDelivery(OrderService.java:67)

public class OrderService {
    public boolean validateDelivery(Order order) {
        Customer customer = order.getCustomer();
        // Line 67: customer.getAddress() returns null, then we call .getCity() on null
        String city = customer.getAddress().getCity();

        // Better approach: check at each step
        if (customer.getAddress() == null) {
            throw new IllegalStateException("Customer address is required");
        }
        return deliveryService.canDeliver(city);
    }
}

// Stack trace tells us EXACTLY what was null: customer.getAddress()
// Pre-Java 14 would just say NPE at line 67 — you'd check customer, getAddress(), and getCity()
// Java 14+ names the exact method call that returned null

