//     at com.example.math.Factorial.calculate(Factorial.java:8)
//     at com.example.math.Factorial.calculate(Factorial.java:8)
//     at com.example.math.Factorial.calculate(Factorial.java:8)
//     at com.example.math.Factorial.calculate(Factorial.java:8)
//     ... (repeated 1024 times)

public class Factorial {
    // BROKEN: Missing base case causes infinite recursion
    public int calculate(int n) {
        return n * calculate(n - 1);  // line 8 — calls itself forever
    }

    // FIXED: Base case stops recursion
    public int calculateCorrect(int n) {
        if (n <= 1) {  // base case prevents infinite calls
            return 1;
        }
        return n * calculateCorrect(n - 1);
    }
}

// The stack trace shows calculate() calling itself repeatedly
// Each call adds a frame to the stack until it overflows
// Fix: Always have a condition that stops the recursion

