//     at org.springframework.orm.jpa.vendor.HibernateJpaDialect.convertHibernateAccessException
// Caused by: java.sql.SQLException: Duplicate entry '12345' for key 'PRIMARY'
//     at com.mysql.cj.jdbc.exceptions.SQLError.createSQLException

public class OrderService {
    public void createOrder(Long customerId, String item) {
        try {
            var order = new Order(customerId, item);
            orderRepository.save(order);  // throws DataAccessException
        } catch (DataAccessException e) {
            // Wrap low-level exception in business exception, preserving cause
            throw new OrderException(
                "Failed to create order for customer " + customerId,
                e  // original exception becomes the cause
            );
        }
    }
}

// The chain shows: OrderException → DataIntegrityViolationException → SQLException
// Root cause (SQLException) tells us exactly what went wrong: duplicate primary key

