// Exception in thread "main" java.lang.StackOverflowError
//     at com.example.math.Fibonacci.calculate(Fibonacci.java:6)
//     at com.example.math.Fibonacci.calculate(Fibonacci.java:6)
//     at com.example.math.Fibonacci.calculate(Fibonacci.java:6)
//     at com.example.math.Fibonacci.calculate(Fibonacci.java:6)
//     ... (repeats thousands of times)

public class Fibonacci {
    // BROKEN: Missing base case leads to infinite recursion
    public int calculate(int n) {
        return calculate(n - 1) + calculate(n - 2);  // line 6 — never stops
    }

    // FIXED: Base cases prevent infinite recursion
    public int calculateCorrect(int n) {
        if (n <= 1) {  // base case: stop recursing
            return n;
        }
        return calculateCorrect(n - 1) + calculateCorrect(n - 2);
    }
}

// Each recursive call adds a frame to the call stack
// Without a base case, frames accumulate until stack overflows
